const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Taiwan geometry
  var taiwan = ee.Geometry.Rectangle([119.5, 21.5, 122.5, 25.5]);

  // Define time periods
  var period1_start = '2020-02-10';
  var period1_end = '2020-02-25';
  var period2_start = '2020-04-20';
  var period2_end = '2020-05-12';

  // Function to process NO2 data
  function processNO2Collection(startDate, endDate) {
    var collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterDate(startDate, endDate)
      .filterBounds(taiwan)
      .select(['tropospheric_NO2_column_number_density', 'qa_value']);

    // Apply quality mask (qa_value > 0.5 for good quality)
    var maskedCollection = collection.map(function(image) {
      var quality = image.select('qa_value');
      var no2 = image.select('tropospheric_NO2_column_number_density');
      return no2.updateMask(quality.gt(0.5));
    });

    return maskedCollection;
  }

  // Get collections for both periods
  var period1_col = processNO2Collection(period1_start, period1_end);
  var period2_col = processNO2Collection(period2_start, period2_end);

  // Check collection sizes
  var period1_size = period1_col.size().getInfo();
  var period2_size = period2_col.size().getInfo();

  print('Period 1 (Feb 10-25) Images: ' + period1_size);
  print('Period 2 (Apr 20-May 12) Images: ' + period2_size);

  // Handle empty collections
  if (period1_size === 0 || period2_size === 0) {
    print('<answer>C1</answer>');
    return;
  }

  // Create mean composites and calculate statistics
  var period1_mean = period1_col.mean();
  var period2_mean = period2_col.mean();

  // Calculate mean NO2 values over Taiwan
  var period1_stats = period1_mean.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: taiwan,
    scale: 1000,
    maxPixels: 1e9
  });

  var period2_stats = period2_mean.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: taiwan,
    scale: 1000,
    maxPixels: 1e9
  });

  var p1_result = period1_stats.getInfo();
  var p2_result = period2_stats.getInfo();

  var p1_mean = p1_result.tropospheric_NO2_column_number_density;
  var p1_count = p1_result.tropospheric_NO2_column_number_density_count;
  var p2_mean = p2_result.tropospheric_NO2_column_number_density;
  var p2_count = p2_result.tropospheric_NO2_column_number_density_count;

  print('Period 1 Mean NO2: ' + (p1_mean ? p1_mean.toFixed(6) : 'No data'));
  print('Period 1 Valid Pixels: ' + p1_count);
  print('Period 2 Mean NO2: ' + (p2_mean ? p2_mean.toFixed(6) : 'No data'));
  print('Period 2 Valid Pixels: ' + p2_count);

  // Check for no valid pixels
  if (p1_count === 0 || p2_count === 0) {
    print('<answer>C2</answer>');
    return;
  }

  // Check for invalid calculations
  if (p1_mean === null || p2_mean === null || 
      isNaN(p1_mean) || isNaN(p2_mean) ||
      p1_mean < 0 || p2_mean < 0) {
    print('<answer>C3</answer>');
    return;
  }

  // Compare means and determine answer
  if (p2_mean > p1_mean) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
